const { writeFileSync } = await import('node:fs');
const markdown = process.env.MARKDOWN;
if (!markdown) throw new Error('Missing MARKDOWN env var');
const path = '/tmp/input.md';
writeFileSync(path, markdown, 'utf8');
globalThis.inputPath = path;
globalThis.markdown = markdown;

const { readFileSync } = await import('node:fs');
const { marked } = await import('marked');
const md = globalThis.markdown ?? readFileSync(globalThis.inputPath, 'utf8');
const html = marked.parse(md);
globalThis.html = html;
